INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(901, 'Genesis 31:43', 'Genesis', 31, 43, '&nbsp;بيا لابن يعقوب له جواب ورکړو، ”دا ځوانې ښځې زما لوڼه دى، د دوئ بچى زما دى او دا رَمې زما دى. چې تۀ دلته څۀ هم ګورې هغه زما دى. خو زۀ خپلې لوڼه او د هغوئ بچى نۀ شم ساتلے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(902, 'Genesis 31:44', 'Genesis', 31, 44, '&nbsp;نو زۀ تا سره يو لوظ کولو ته تيار يم. راځه چې داسې څۀ وکړُو چې زمونږ دا لوظ پرې مونږ ته راياديږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(903, 'Genesis 31:45', 'Genesis', 31, 45, '&nbsp;نو يعقوب يوه تيږه راواخستله او هغه يې د يو يادګار په توګه ودروله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(904, 'Genesis 31:46', 'Genesis', 31, 46, '&nbsp;هغۀ خپلو سړو ته وفرمائيل چې، ”څۀ کاڼى راټول کړئ.“ نو هغوئ کاڼى راټول کړل او يو ډېرے يې ترې نه جوړ کړو. بيا هغوئ د هغه کاڼو د ډېرى سره روټۍ وخوړله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(905, 'Genesis 31:47', 'Genesis', 31, 47, '&nbsp;لابن په دې يجرشاهدوتها نوم کېښودو، خو يعقوب پرې جلعيد نوم کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(906, 'Genesis 31:48', 'Genesis', 31, 48, '&nbsp;لابن يعقوب ته ووئيل، ”دا د کاڼو ډېرے به زمونږ د دواړو دپاره يو يادګار وى.“ نو ځکه د هغه ځائ نوم جلعيد شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(907, 'Genesis 31:49', 'Genesis', 31, 49, '&nbsp;لابن دا هم ووئيل، ”مالِک خُدائ دې په مونږ نظر وساتى چې کله مونږ د يو بل نه جدا يُو.“ نو د هغه ځائ نوم مصفاه هم شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(908, 'Genesis 31:50', 'Genesis', 31, 50, '&nbsp;لابن ووئيل، ”کۀ تۀ زما د لوڼو سره بد سلوک کوې يا نورې ښځې وادۀ کوې، کۀ ما ته پته هم نۀ وى، ياد لره چې خُدائ پاک مونږ ګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(909, 'Genesis 31:51', 'Genesis', 31, 51, '&nbsp;دا هغه کاڼى دى چې ما زمونږ په مينځ کښې ډېرے کړى دى او دا هغه يادګارى تيږه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(910, 'Genesis 31:52', 'Genesis', 31, 52, '&nbsp;دا ډېرے او دا د يادګارى تيږه دواړه يادګارونه دى. زۀ به کله هم په تا حمله کولو دپاره د دې نه نۀ درتېرېږم او تۀ هم په ما حمله کولو دپاره د دې يادګارى تيږې نه مۀ راتېرېږه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(911, 'Genesis 31:53', 'Genesis', 31, 53, '&nbsp;د اِبراهيم خُدائ پاک او د نحور خُدائ پاک به په مونږ نظر وکړى چې مونږ کومه معاهده کړې ده چې د هغې خيال ساتو.“ بيا يعقوب د هغه خُدائ پاک په نوم د کوم چې د هغۀ پلار اِسحاق عبادت کولو پوخ لوظ وکړو چې دا وعده به پوره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(912, 'Genesis 31:54', 'Genesis', 31, 54, '&nbsp;هغۀ يو ځناور حلال کړو او دا يې په غر باندې د قربانۍ په توګه پېش کړو او يعقوب روټۍ له د هغۀ خپلوان راوغوښتل، دوئ روټۍ وخوړه او بيا يې په غر باندې شپه تېره کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(913, 'Genesis 31:55', 'Genesis', 31, 55, '&nbsp;بل سحر وختى لابن خپل نمسى او لوڼه ښُکل کړل او په مخه ښه يې ورته ووئيل او واپس کور ته روان شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(914, 'Genesis 32:1', 'Genesis', 32, 1, '&nbsp;چې يعقوب څنګه خپل مُلک ته لاړو، د خُدائ پاک څۀ فرښتې ورسره مِلاو شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(915, 'Genesis 32:2', 'Genesis', 32, 2, '&nbsp;چې هغه يې وليدلې، نو وې فرمائيل، ”دا د خُدائ پاک لښکر دے.“ نو په هغه ځائ يې محنايم نوم کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(916, 'Genesis 32:3', 'Genesis', 32, 3, '&nbsp;يعقوب د خپل ځان نه مخکښې د ادوم په مُلک کښې د سعير په علاقه کښې خپل ورور ته پېغام وړُونکى ولېږل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(917, 'Genesis 32:4', 'Genesis', 32, 4, '&nbsp;هغۀ ورته ووئيل چې، ”زما نېک عِيسو ته دا پېغام ورسوئ، زۀ ستا تابعدار خِدمتګار يعقوب يم، چې د ډېر وخت نه د لابن سره د يو مسافر په شان دېره يم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(918, 'Genesis 32:5', 'Genesis', 32, 5, '&nbsp;زۀ غوَيى، خرۀ، ګډې، چېلۍ او نوکران لرم. نېکه، زۀ تا له خبر درلېږم، د دې دپاره چې ستا په نظر کښې ښۀ راشم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(919, 'Genesis 32:6', 'Genesis', 32, 6, '&nbsp;کله چې هغه پېغام وړُونکى يعقوب ته واپس راغلل، هغوئ ووئيل، ”مونږ ستا ورور عِيسو له لاړُو او هغه د مخکښې نه تا سره مِلاوېدو دپاره راروان دے. څلور سوه کسان ورسره دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(920, 'Genesis 32:7', 'Genesis', 32, 7, '&nbsp;يعقوب سخت ويرېدو او پرېشانه شو. د هغۀ سره چې کوم خلق او رَمې، غواګانې او اوښان وُو هغه يې په دوو ډلو کښې تقسيم کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(921, 'Genesis 32:8', 'Genesis', 32, 8, '&nbsp;د هغۀ خيال دا وو، ”کۀ عِيسو راشى او هغه وړومبۍ ډله ختمه کړى نو هغه بله ډله چې کومه پاتې وى هغه به وتښتى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(922, 'Genesis 32:9', 'Genesis', 32, 9, '&nbsp;بيا يعقوب دُعا وکړه، ”زما د نيکۀ اِبراهيم خُدايه پاکه او زما د پلار اِسحاق خُدايه پاکه، زما سوال واوره، مالِکه خُدايه. تا ما ته ووئيل چې خپل مُلک او خپلو خپلوانو له لاړ شه او تۀ به زما دپاره هر څۀ سم کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(923, 'Genesis 32:10', 'Genesis', 32, 10, '&nbsp;تا چې خپل خِدمت کوونکى ته، کومه مِهربانى او وفادارى ښودلې ده زۀ د هغې قابل نۀ يم، زۀ چې د اُردن سيند نه پورېوتم نو زما سره هيڅ هم نۀ وُو صِرف يوه امسا وه او اوس زما نه دوه قبيلې جوړې شوې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(924, 'Genesis 32:11', 'Genesis', 32, 11, '&nbsp;زۀ تا ته سوال کوم چې ما د خپل ورور عِيسو نه بچ کړه. زۀ يرېږم هسې نه چې هغه په مونږ حمله وکړى نو مونږ به سره د ښځو او ماشومانو ټول تباه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(925, 'Genesis 32:12', 'Genesis', 32, 12, '&nbsp;هغه وعده راياده کړه چې تا زما سره کړې وه چې زما دپاره به هر څۀ سم کړې او ما له به دومره اولاد راکړې چې څوک به يې شمېرلے نۀ شى، دومره ډېر لکه چې د سمندر په غاړه شګې دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(926, 'Genesis 32:16', 'Genesis', 32, 16, '&nbsp;هغۀ دا په مختلفو ډلو کښې تقسيم کړل او د خپلو نوکرانو نه يې يو يو په هره ډله مشران مقرر کړل. هغۀ ورته ووئيل، ”زما نه مخکښې لاړ شئ او د مخکښې قبيلې او ورپسې راروانې قبيلې په مينځ کښې فاصله وساتئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(927, 'Genesis 32:17', 'Genesis', 32, 17, '&nbsp;هغۀ وړومبى نوکر له حُکم ورکړو، ”زما ورور عِيسو چې درسره ملاويږى او تپوس کوى چې، ستا نېک څوک دے؟ تۀ چرته ځې؟ ستا نه مخکښې دا ځناور د چا دى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(928, 'Genesis 32:18', 'Genesis', 32, 18, '&nbsp;نو ته ورته وايه چې دا ستا د خِدمتګار يعقوب دى. هغه دا خپل نېک عِيسو له په تُحفه کښې لېږى. او يعقوب په خپله په مونږ پسې راروان دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(929, 'Genesis 32:19', 'Genesis', 32, 19, '&nbsp;هغۀ دوېم او درېم له هم دغه شان حُکم ورکړو او هغه ټولو له چې کوم د ډلو مشران وُو، ”تاسو به خامخا داسې وايئ چې کله تاسو د عِيسو سره مِلاوېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(930, 'Genesis 32:20', 'Genesis', 32, 20, '&nbsp;تاسو به خامخا وايئ چې ستا خِدمتګار يعقوب په خپله په مونږ پسې راروان دے.“ د يعقوب خيال دا وو چې، ”زۀ به د دې تُحفو سره د هغۀ غصه سړه کړم او چې کله ورسره مخامخ شم کېدے شى چې هغه ما ته په خېر راغلے ووائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(931, 'Genesis 32:21', 'Genesis', 32, 21, '&nbsp;هغۀ هغه تُحفې د ځان نه مخکښې ولېږلې او هغه شپه په محنايم کښې پاتې شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(932, 'Genesis 32:22', 'Genesis', 32, 22, '&nbsp;هم په هغه شپه يعقوب پاڅېدو، هغۀ خپلې دوه نِکاح کړې ښځې، د هغۀ دوه نورې ښځې او خپل يوولس زامن روان کړل او د يبوق د سيند نه په ګودر يعنې هغه ځائ کښې پورې وتل چرته چې اوبۀ کمې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(933, 'Genesis 32:23', 'Genesis', 32, 23, '&nbsp;هغۀ هغوئ روان کړل او پورې يې ويستل، د هغۀ سره چې څۀ وُو هغه يې هم بلې غاړې ته ولېږل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(934, 'Genesis 32:24', 'Genesis', 32, 24, '&nbsp;خو هغه يواځې پاتې شو. بيا يو سړے راغلو او د هغۀ سره يې د سحر د رڼا پورې کُشتى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(935, 'Genesis 32:25', 'Genesis', 32, 25, '&nbsp;چې کله هغه سړى ته پته ولګېده چې مقابله يې نۀ شوه ګټلے، نو هغۀ يعقوب په پتُون ووهلو او پتُون يې د بند نه ووتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(936, 'Genesis 32:26', 'Genesis', 32, 26, '&nbsp;هغه سړى ووئيل، ”د سحر رڼا شوه، ما پرېږده چې لاړ شم.“ يعقوب ورته وفرمائيل، ”زۀ به تا کله هم نۀ پرېږدم، چې ترڅو پورې دې ما له برکت نۀ وى راکړے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(937, 'Genesis 32:27', 'Genesis', 32, 27, '&nbsp;هغه سړى ترې تپوس وکړو، ”ستا څۀ نوم دے؟“ نو هغۀ ورته ووئيل، ”يعقوب.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(938, 'Genesis 32:28', 'Genesis', 32, 28, '&nbsp;هغه سړى ورته ووئيل، ”د نن نه پس به ستا نوم يعقوب نۀ وى. تا د خُدائ پاک او د انسان سره مقابله کړې ده او تا ګټلې ده، د اوس نه به ستا نوم اِسرائيل وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(939, 'Genesis 32:29', 'Genesis', 32, 29, '&nbsp;يعقوب ورته وفرمائيل، ”اوس تۀ ما ته خپل نوم وښايه.“ خو هغۀ ورته ووئيل، ”تۀ ولې زما د نوم تپوس کوې؟“ بيا هغۀ يعقوب له برکت ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(940, 'Genesis 32:30', 'Genesis', 32, 30, '&nbsp;يعقوب ووئيل، ”ما خُدائ پاک مخامخ ليدلے دے او بيا هم لا ژوندے پاتې يم.“ نو په هغه ځائ يې فنواېل نوم کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(941, 'Genesis 32:31', 'Genesis', 32, 31, '&nbsp;نمر راختلو چې يعقوب د فنواېل نه تلو او د خپل پتُون په وجه ګډ ګډ روان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(942, 'Genesis 32:32', 'Genesis', 32, 32, '&nbsp;تر نن ورځې پورې د بنى اِسرائيلو اولاد هغه پله نۀ خورى کومه چې د پتُون په بند پورې وى، ځکه چې د پتُون د بند هم په دې ځائ هغۀ يعقوب وهلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(943, 'Genesis 33:1', 'Genesis', 33, 1, '&nbsp;يعقوب چې وکتل نو عِيسو يې وليدو او څۀ ګورى چې څلور سوه کسان ورسره راروان وُو. نو هغۀ خپل بچى په لِياه، راحيل او په هغه دوو نورو ښځو باندې تقسيم کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(944, 'Genesis 33:2', 'Genesis', 33, 2, '&nbsp;هغۀ نورې ښځې او د هغوئ بچى مخکښې کړل، بيا يې لِياه او د هغې بچى کړل او راحيل او يوسف يې وروستو کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(945, 'Genesis 33:3', 'Genesis', 33, 3, '&nbsp;يعقوب د دوئ نه مخکښې لاړو او چې څنګه خپل ورور ته ورسېدو، نو ټيټ شو او اووۀ ځل يې تندې په زمکه ولګولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(946, 'Genesis 33:4', 'Genesis', 33, 4, '&nbsp;خو عِيسو مِلاوېدو دپاره هغۀ له ورمنډه کړه او د هغۀ نه يې لاسونه تاو کړل، راغاړه يې ويستلو او ښُکل يې کړو. دوئ دواړو وژړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(947, 'Genesis 33:5', 'Genesis', 33, 5, '&nbsp;چې کله عِيسو وکتل او هغه ښځې او ماشومان يې وليدل، نو هغۀ تپوس وکړو، ”دا تا سره څوک دى؟“ يعقوب ورته وفرمائيل، ”صاحِبه، خُدائ پاک په ما ډېر مهربانه دے او دا بچى يې راکړى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(948, 'Genesis 33:6', 'Genesis', 33, 6, '&nbsp;بيا هغه نورې ښځې او د هغوئ بچى رامخکښې شول او ورته ټيټ شول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(949, 'Genesis 33:7', 'Genesis', 33, 7, '&nbsp;بيا لِياه او د هغې بچى راغلل او په آخر کښې يوسف او راحيل راغلل او ورته ټيټ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(950, 'Genesis 33:8', 'Genesis', 33, 8, '&nbsp;عِيسو ترې تپوس وکړو، ”د هغې بلې قبيلې سره چې زۀ مِلاو شوم هغه دې د څۀ مقصد دپاره راوستلې ده؟“ يعقوب ورته وفرمائيل، ”د دې دپاره چې زما نېک راسره ښۀ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(951, 'Genesis 33:9', 'Genesis', 33, 9, '&nbsp;خو عِيسو ورته ووئيل، ”زما وروره، زما سره هر څۀ ډېر دى، چې تا سره هم څۀ دى هغه د ځان دپاره وساته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(952, 'Genesis 33:10', 'Genesis', 33, 10, '&nbsp;يعقوب ووئيل، ”نه، زۀ تا ته سوال کوم، کۀ تۀ په ما مهربانه يې، نو زما د لاسونو نه دا تُحفه قبوله کړه. چې ستا مخ ته مې وکتل دا داسې شوه لکه چې د خُدائ پاک مخ ته مې کتلى وى، ځکه چې تۀ اوس ما سره ډېر ښۀ يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(953, 'Genesis 33:11', 'Genesis', 33, 11, '&nbsp;زۀ تا ته سوال کوم چې دا تُحفه زما نه قبوله کړه کومه چې ما تا له راوړې ده، خُدائ پاک په ما مهربانه دے او چې د څۀ څيز هم ضرورت وو هغه يې راکړے دے.“ يعقوب په هغۀ زور راوړو نو هغه يې قبوله کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(954, 'Genesis 33:12', 'Genesis', 33, 12, '&nbsp;عِيسو ووئيل، ”ځئ چې په خپل سفر باندې ځُو. زۀ به تاسو سره ځم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(955, 'Genesis 33:13', 'Genesis', 33, 13, '&nbsp;يعقوب ووئيل، ”زما نېکه، تا ته پته ده چې ماشومان کمزورى دى، او په کار دى چې زۀ د دې ګډو او څاروو او د دوئ د بچو خيال وساتم. کۀ دا مونږ يوه ورځ هم تېز بوځُو، نو ټول څاروى به مړۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(956, 'Genesis 33:14', 'Genesis', 33, 14, '&nbsp;زۀ خپل نېک ته سوال کوم چې د خپل خِدمتګار نه مخکښې لاړ شى او نېکه، زۀ به په مزه مزه د څاروو او د هغوئ د بچو په قدم په تا پسې درځم او په ادوم کښې به درسره مِلاو شم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(957, 'Genesis 33:15', 'Genesis', 33, 15, '&nbsp;عِيسو ووئيل، ”زۀ به تا سره زما خپل څۀ کسان پرېږدم.“ خو يعقوب ورته وفرمائيل، ”د دې هيڅ حاجت نشته، زۀ صِرف دا غواړم چې ستا په نظر کښې ښۀ راشم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
