(991, 'Genesis 34:29', 'Genesis', 34, 29, '&nbsp;دوئ مال دولت يوړو، ټولې ښځې او ماشومان يې ونيول او د کورونو نه يې هر څۀ لوټ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(992, 'Genesis 34:30', 'Genesis', 34, 30, '&nbsp;يعقوب، شمعون او ليوى ته ووئيل، ”تاسو زۀ په تکليف کښې اچولے يم، اوس به کنعانيان، فرزيان او د دې مُلک هر يو کس زما نه نفرت کوى. زما سره دومره سړى نشته، کۀ دوئ ټول زما خِلاف يو ځائ شى او په ما حمله وکړى نو زمونږ مکمل خاندان به تباه شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(993, 'Genesis 34:31', 'Genesis', 34, 31, '&nbsp;خو هغوئ ووئيل، ”مونږ دا نۀ شُو زغملے چې زمونږ خور سره دې د کنجرې په شان سلوک وشى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(994, 'Genesis 35:1', 'Genesis', 35, 1, '&nbsp;څۀ موده وروستو خُدائ پاک يعقوب ته ووئيل، ”پاڅه او سمدستى بيت‌ايل ته لاړ شه او هلته اوسېږه. هلته ما ته يوه قربان‌ګاه جوړه کړه. زۀ هغه خُدائ پاک يم چې تا ته راڅرګند شوے وم چې کله تۀ د خپل ورور عِيسو نه تښتېدلې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(995, 'Genesis 35:2', 'Genesis', 35, 2, '&nbsp;نو يعقوب خپل خاندان ته او هغه ټولو ته چې د هغۀ سره وُو ووئيل، ”تاسو سره چې کوم پردى بُتان دى هغه وغورزوئ، خپل ځانونه پاک کړئ او صفا جامې واغوندئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(996, 'Genesis 35:3', 'Genesis', 35, 3, '&nbsp;مونږ به د دې ځائ نه بيت‌ايل ته ځُو، هلته به زۀ خُدائ پاک ته يوه قربان‌ګاه جوړه کړم چا چې په تکليف کښې زما سوال اورېدلے دے او چې زۀ چرته هم تلے يم نو هغه زما مل وو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(997, 'Genesis 35:4', 'Genesis', 35, 4, '&nbsp;نو هغوئ هغه ټول پردى بُتان چې د دوئ سره وُو او د دوئ په غوږُونو کښې چې کومې والۍ وې، هغه يې يعقوب له ورکړې. هغۀ دا شِکم ته نزدې د څېړۍ د ونې لاندې ښخ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(998, 'Genesis 35:5', 'Genesis', 35, 5, '&nbsp;چې کله يعقوب او د هغۀ زامن په سفر روان وُو، نو د ګېرچاپېره ښارونو په خلقو باندې د خُدائ پاک سخته يره راغله، نو هيڅ څوک ورپسې نۀ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(999, 'Genesis 35:6', 'Genesis', 35, 6, '&nbsp;يعقوب د خپلو ټولو خلقو سره لوز ته راغلو، کوم چې د کنعان په مُلک کښې په بيت‌ايل مشهور دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(1000, 'Genesis 35:7', 'Genesis', 35, 7, '&nbsp;هغۀ هلته يوه قربان‌ګاه جوړه کړه او په هغه ځائ يې ”د بيت‌ايل خُدائ پاک“ نوم کېښودو، ځکه چې خُدائ پاک هغۀ ته هلته راڅرګند شوے وو کله چې هغه د خپل ورور نه تښتېدلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');